def transform(grid):
    """Copy the marked pattern to every translated placement over zero cells."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    # The task's object is the unique color other than the two noisy background colors.
    # Choose the rare accent color (the existing template pixels).
    counts = {v: sum(row.count(v) for row in grid) for v in colors}
    accent = min(colors, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == accent]
    # All template pixels are retained; find other translations whose corresponding
    # cells are zero in the original noisy field.
    out = [row[:] for row in grid]
    for dr in range(-h, h):
        for dc in range(-w, w):
            if dr == 0 and dc == 0:
                continue
            dest = [(r + dr, c + dc) for r, c in points]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] == 0 for r, c in dest):
                for r, c in dest:
                    out[r][c] = accent
    return out

